-- ==============================================================================
-- MIGRATION 202: EMENDAS — NOMES GENÉRICOS DOS BENEFICIÁRIOS
-- Versão: 20261026000202_emendas_beneficiarios_nomes_genericos.sql
--
-- Pedido de 26/10/2026: cadastros com nome genérico ("Corpo de Bombeiros Militar", "Polícia Militar", "Guarda
-- Municipal", "Delegacia de Polícia"...) não diziam qual unidade era. Regras aprovadas pelo usuário:
--   - órgão do estado inteiro ou da capital → "Polícia Militar do Estado de São Paulo" (DF: "do Distrito Federal");
--   - guarda municipal → "Guarda Municipal de <Cidade>" (Guarda Civil Municipal entra no mesmo padrão);
--   - genérico numa cidade do interior → nome oficial da unidade daquela cidade, pesquisado em fonte oficial
--     (lista de unidades da PMESP, decretos de SP na Alesp, Portaria 043/PMMS + Decreto MS 16.350/2023, sites da
--     PCMS, PJC-MT, PCBA, CBMSC, Brigada Militar), sempre pelo nome mais novo;
--   - "Sampaio"/SP não existe: é Teodoro Sampaio;
--   - quando a cidade tem mais de uma unidade do mesmo tipo, as duas ficam cadastradas (cadastro novo sem indicação,
--     com o CNPJ do mesmo órgão).
-- Cadastros que passam a ter o mesmo nome e cidade de outro são juntados (fica o específico ou o com mais indicações).
-- O nome antigo vai para outros_nomes (a busca continua achando). Cada mudança só vale para o cadastro que ainda está
-- na versão medida em 26/10/2026 (o que a CAEP editou depois fica como está).
-- Lista de conferência: .claude/relatorios/nomes-genericos-beneficiarios-2026-10-26.html (fora do repositório).
-- ==============================================================================

-- 1) Junções ------------------------------------------------------------------
CREATE TEMP TABLE juncoes_202 AS
SELECT v.fica_id, v.sai_id, s.nome AS sai_nome, s.cnpj AS sai_cnpj, s.outros_nomes AS sai_outros,
       (SELECT count(*) FROM public.emenda_pedido_linhas l WHERE l.beneficiario_id = v.sai_id) AS linhas
  FROM (VALUES
  ('644ebce7-c93b-4126-9e98-aa5e4467a8f0'::uuid, 6, 'c571f5f9-e0ca-4639-b043-12572f4e8301'::uuid, 4),
  ('bec9c842-0284-4524-b6de-a8a39018d363'::uuid, 3, '94ae81cb-291e-4c93-872c-91484af7df8f'::uuid, 4),
  ('cd5c2a3c-af95-4054-8ee9-048b29c38a8a'::uuid, 3, 'c429bd41-8526-4a7e-aa53-90a9ed71cd4a'::uuid, 3),
  ('0d09ef54-cd7f-4eff-836c-2709fed57289'::uuid, 3, 'a6055d7f-11ba-4490-a3fa-5579e8b6c61e'::uuid, 3),
  ('3bf26a58-fef3-406d-a923-8eaad35fc346'::uuid, 4, 'fbf6428d-2e6a-4e1c-897e-bf55c7ff0c53'::uuid, 4),
  ('dc911f3d-0855-47f9-bf3e-6ade488643d1'::uuid, 3, 'd172181f-1974-4f6b-82b3-31b41aeb22c5'::uuid, 3),
  ('1d6a16de-ddd1-45e5-8de8-b16393a30315'::uuid, 3, '3db05d04-4e77-4013-8420-0cfa2f778b94'::uuid, 3),
  ('2be3fc75-80bd-4c0a-ad3a-7511ffe297b7'::uuid, 3, 'a2050c8e-4714-4c07-a902-8c323810c4c3'::uuid, 3),
  ('c8a9ec10-0049-4fe4-a0f3-fc17f82469b9'::uuid, 3, 'ba4392cc-f46d-417f-afde-d9b1e732dd7c'::uuid, 3),
  ('77ad07ad-a498-4dbd-bdd2-dfe069d857bc'::uuid, 3, '1e2679a9-a888-473b-a812-93270128f659'::uuid, 3),
  ('b7bffacd-5b7c-443e-ac84-9a0d4f333238'::uuid, 3, '6673a40d-303e-49b8-b4b3-efa55e623576'::uuid, 3),
  ('db59a032-1cb7-4678-b9ff-f9ed83c33705'::uuid, 3, '428dbdfe-a0d1-4a04-ad17-d33d1bc83495'::uuid, 3),
  ('b7a21385-fcfa-44e1-ae31-a403ef31014c'::uuid, 4, 'a9dd44f8-c892-4088-92e8-f2c787e3d079'::uuid, 4)
  ) v(fica_id, fica_versao, sai_id, sai_versao)
  JOIN public.emenda_beneficiarios f ON f.id = v.fica_id AND f.versao = v.fica_versao
  JOIN public.emenda_beneficiarios s ON s.id = v.sai_id AND s.versao = v.sai_versao;

UPDATE public.emenda_pedido_linhas l SET beneficiario_id = j.fica_id FROM juncoes_202 j WHERE l.beneficiario_id = j.sai_id;

INSERT INTO public.emenda_beneficiarios_juntados (ficou_id, ficou_nome, saiu_id, saiu_nome, saiu_cnpj, linhas, motivo, juntado_por_nome)
SELECT j.fica_id, f.nome, j.sai_id, j.sai_nome, j.sai_cnpj, j.linhas,
       'Mesma unidade depois de trocar o nome genérico (migration 202)', 'Nomes genéricos (migration 202)'
  FROM juncoes_202 j JOIN public.emenda_beneficiarios f ON f.id = j.fica_id;

UPDATE public.emenda_beneficiarios f SET
  outros_nomes = ARRAY(SELECT DISTINCT x FROM unnest(f.outros_nomes || g.nomes) x WHERE x <> f.nome ORDER BY x)
  FROM (SELECT j.fica_id, array_agg(j.sai_nome) || COALESCE(array_agg(o) FILTER (WHERE o IS NOT NULL), '{}') AS nomes
          FROM juncoes_202 j LEFT JOIN LATERAL unnest(j.sai_outros) o ON TRUE GROUP BY j.fica_id) g
 WHERE f.id = g.fica_id;

DELETE FROM public.emenda_beneficiarios WHERE id IN (SELECT sai_id FROM juncoes_202);

