  ) v(id, versao, nome, sigla, municipio, uf)
  JOIN public.emenda_beneficiarios b ON b.id = v.id
 WHERE b.versao = v.versao;

UPDATE public.emenda_beneficiarios b SET
  nome = COALESCE(r.nome, b.nome),
  sigla = COALESCE(r.sigla, b.sigla),
  entrega_municipio = COALESCE(r.municipio, b.entrega_municipio),
  entrega_uf = COALESCE(r.uf, b.entrega_uf),
  outros_nomes = CASE WHEN r.nome IS NULL OR r.antes = r.nome OR r.antes = ANY(b.outros_nomes) THEN b.outros_nomes
                      ELSE ARRAY(SELECT DISTINCT x FROM unnest(array_append(b.outros_nomes, r.antes)) x WHERE x <> r.nome ORDER BY x) END,
  versao = b.versao + 1, atualizado_por = NULL, atualizado_por_nome = 'Nomes genéricos (migration 202)', atualizado_em = NOW()
  FROM dados_202 r
 WHERE b.id = r.id;

-- 3) Cadastros novos (mais de uma unidade do mesmo tipo na cidade) ------------
INSERT INTO public.emenda_beneficiarios
  (nome, sigla, entrega_municipio, entrega_uf, origem, cnpj, razao_social, natureza_juridica, ente_federativo,
   situacao_cadastral, sede_endereco, sede_municipio, sede_uf, sede_cep, sede_telefone, sede_email, receita_lida_em,
   criado_por_nome, atualizado_por_nome)
SELECT v.nome, v.sigla, v.municipio, v.uf, 'CADASTRO', i.cnpj, i.razao_social, i.natureza_juridica, i.ente_federativo,
       i.situacao_cadastral, i.sede_endereco, i.sede_municipio, i.sede_uf, i.sede_cep, i.sede_telefone, i.sede_email,
       i.receita_lida_em, 'Nomes genéricos (migration 202)', 'Nomes genéricos (migration 202)'
  FROM (VALUES
  ('40º Batalhão de Polícia Militar Metropolitano', '40º BPM/M', 'São Bernardo do Campo', 'SP', '4834ae12-d5d6-4ec1-ad61-8b72f6a07798'::uuid),
  ('Delegacia de Polícia de Investigações sobre Entorpecentes de Limeira', 'DISE Limeira', 'Limeira', 'SP', 'aada8e4a-2b99-49b8-9511-442fdc4c7b35'::uuid),
  ('1ª Delegacia Territorial de Vitória da Conquista', '1ª DT/10ª COORPIN', 'Vitória da Conquista', 'BA', 'a6f3f31d-8b09-45ad-bff1-41c2fc60a00e'::uuid),
  ('2ª Delegacia Territorial de Vitória da Conquista', '2ª DT/10ª COORPIN', 'Vitória da Conquista', 'BA', 'a6f3f31d-8b09-45ad-bff1-41c2fc60a00e'::uuid),
  ('2ª Delegacia de Polícia de Ponta Porã', '2ª DP Ponta Porã', 'Ponta Porã', 'MS', '9ead7593-78ea-4d8b-b817-b25fbafcc97c'::uuid)
  ) v(nome, sigla, municipio, uf, irmao_id)
  LEFT JOIN public.emenda_beneficiarios i ON i.id = v.irmao_id
 WHERE NOT EXISTS (SELECT 1 FROM public.emenda_beneficiarios e
                    WHERE e.chave_identidade = public.chave_nome_beneficiario(v.nome || ' ' || v.municipio || ' ' || v.uf));

